"""PSLE-style items for sci-systems-circuit-vars (file sci-circuit-vars.json), all tiers (round sci-fill-circuit-vars-2026-11-20)."""
from fillkit import add, table, lint
from figs_circuit import circuit, pair

SUB, FILE = "sci-systems-circuit-vars", "sci-circuit-vars.json"
CV, FT, RD = "sci-pat-circuit-variables", "sci-pat-fair-test-design", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)
def cs(n, bulbs=1, cap=None): return circuit([[("L", "P") if bulbs == 1 else ("L", "P"), ] + ([("L", "Q")] if bulbs == 2 else []), [("S", "S", True), ("B", n)]], caption=cap, W=230 if bulbs == 1 else 270)
def cp(n, cap=None): return circuit(main=("S", "S", True), rows=[[("L", "P")], [("L", "Q")], [("B", n)]], caption=cap, W=240)
def two(a, b): return lambda: pair([a("Circuit A"), b("Circuit B")])

# ---------------- basic ----------------
q("cv-001", B, 1, CV, "A bulb is lit by one battery. A second battery is added in series. What happens to the bulb?", "It becomes brighter", [W("It becomes dimmer", "reversed", "More batteries in series push more current."), W("It stays the same", "wrong-idea", "The extra battery gives more energy."), W("It goes out", "wrong-idea", "The bulb still has a complete circuit.")], ["More cells in series give a larger current, so the bulb is brighter."], None)
q("cv-002", B, 1, CV, "A second bulb is added in series to a circuit with one battery and one bulb. What happens to the first bulb?", "It becomes dimmer", [W("It becomes brighter", "reversed", "The battery now has to light two bulbs."), W("It stays the same", "wrong-idea", "The current is now smaller."), W("It goes out", "wrong-idea", "The circuit is still complete.")], ["More bulbs in series make the current smaller."], None)
q("cv-003", B, 1, CV, "Circuits A and B each have a single bulb. Which bulb is brighter?", "The bulb in circuit B", [W("The bulb in circuit A", "reversed", "A has fewer cells, so a smaller current."), W("Both are equally bright", "wrong-idea", "The two circuits have different numbers of cells."), W("Neither will light", "wrong-idea", "Both circuits are closed.")], ["Circuit B has two cells in series, so more current flows."], two(lambda c: cs(1, 1, c), lambda c: cs(2, 1, c)))
q("cv-004", B, 1, CV, "Circuit A has one bulb and circuit B has two bulbs. Which circuit has the brighter bulb or bulbs?", "The bulb in circuit A", [W("The bulb in circuit B", "reversed", "B has two bulbs sharing the same battery."), W("Both are equally bright", "wrong-idea", "B has two bulbs in series."), W("Neither will light", "wrong-idea", "Both circuits are closed.")], ["In A one bulb gets all the current. In B the current is smaller because there are two bulbs."], two(lambda c: cs(1, 1, c), lambda c: cs(1, 2, c)))
q("cv-005", B, 1, CV, "Which circuit has the brightest bulbs?", "Circuit B", [W("Circuit A", "wrong-circuit", "A has the fewest cells."), W("Circuit C", "wrong-circuit", "C has fewer cells than B."), W("They are all equally bright", "wrong-idea", "The numbers of cells are different.")], ["B has the most cells for one bulb."], lambda: pair([cs(1, 1, "Circuit A"), cs(3, 1, "Circuit B"), cs(2, 1, "Circuit C")]))
q("cv-006", B, 1, CV, "What happens to the brightness of a bulb when a battery is added in series?", "It becomes brighter", [W("It becomes dimmer", "reversed", "More energy makes it brighter."), W("It does not change", "wrong-idea", "The current changes."), W("It first brightens and then goes out", "wrong-idea", "It simply stays brighter.")], ["More cells in series give a bigger current."], None)
q("cv-007", B, 2, CV, "Which of the following is a good conductor of electricity?", "A copper wire", [W("A rubber glove", "wrong-material", "Rubber is an insulator."), W("A plastic ruler", "wrong-material", "Plastic is an insulator."), W("A wooden spoon", "wrong-material", "Wood is an insulator.")], ["Copper is a metal and conducts electricity."], None)
q("cv-008", B, 2, CV, "Which of the following is an electrical insulator?", "Rubber", [W("Iron", "wrong-material", "Iron is a metal, so it is a conductor."), W("Aluminium", "wrong-material", "Aluminium is a metal, so it is a conductor."), W("Copper", "wrong-material", "Copper is a metal, so it is a conductor.")], ["Rubber does not let electricity pass through it."], None)
q("cv-009", B, 2, CV, "Which of these is an electrical conductor?", "A steel key", [W("A glass cup", "wrong-material", "Glass is an insulator."), W("A plastic comb", "wrong-material", "Plastic is an insulator."), W("A dry wooden stick", "wrong-material", "Wood is an insulator.")], ["Steel is a metal and conducts electricity."], None)
q("cv-010", B, 2, CV, "Which of the following is an insulator?", "A plastic pen", [W("A copper coin", "wrong-material", "Copper is a conductor."), W("An iron nail", "wrong-material", "Iron is a conductor."), W("An aluminium spoon", "wrong-material", "Aluminium is a conductor.")], ["Plastic is an insulator."], None)
q("cv-011", B, 2, CV, "Why are the handles of screwdrivers used by electricians made of plastic?", "Plastic is an insulator, so electricity does not pass to the hand", [W("Plastic is a conductor, so it carries the electricity away", "reversed", "Plastic is an insulator."), W("Plastic is heavier than metal", "wrong-reason", "Weight is not the reason."), W("Plastic makes the screwdriver shiny", "wrong-reason", "Appearance is not the reason.")], ["An insulating handle keeps the user safe."], None)
q("cv-012", B, 2, CV, "Which of the following is NOT an electrical conductor?", "Dry wood", [W("Copper", "conductor", "Copper is a metal conductor."), W("Iron", "conductor", "Iron is a metal conductor."), W("Aluminium", "conductor", "Aluminium is a metal conductor.")], ["Dry wood does not conduct electricity."], None)
q("cv-013", B, 1, CV, "The bulbs in circuits A and B are the same. How does the brightness of the bulb in A compare with a bulb in B?", "They are equally bright", [W("The bulb in A is brighter", "wrong-idea", "In a parallel circuit each bulb has its own path to the battery."), W("The bulb in B is brighter", "wrong-idea", "Each path has the same current as in A."), W("The bulbs in B are dimmer", "wrong-idea", "Bulbs in separate paths are not dimmer.")], ["In B each bulb has its own path, so it is as bright as the bulb in A."], two(lambda c: cs(2, 1, c), lambda c: cp(2, c)))
q("cv-014", B, 1, CV, "Compare the bulb in circuit A with a bulb in circuit B. Which statement is correct?", "The bulb in A is brighter", [W("The bulb in B is brighter", "reversed", "B's bulbs are in series, sharing the current."), W("They are equally bright", "wrong-idea", "B has two bulbs in series."), W("None of the bulbs light", "wrong-idea", "Both circuits are closed.")], ["The bulb in A has all of the current. In B two bulbs share it."], two(lambda c: cs(2, 1, c), lambda c: cs(2, 2, c)))
q("cv-015", B, 1, CV, "A student adds more cells in series to a circuit with a bulb. What can she expect?", "The bulb becomes brighter", [W("The bulb becomes dimmer", "reversed", "More cells give more current."), W("The bulb stays the same", "wrong-idea", "More cells make a difference."), W("The bulb gets smaller", "wrong-idea", "The bulb does not change size.")], ["More cells give a bigger current."], None)
q("cv-016", B, 2, CV, "Which of the following is a poor conductor of electricity?", "A plastic spoon", [W("A steel spoon", "wrong-material", "Steel is a metal."), W("A copper spoon", "wrong-material", "Copper is a metal."), W("An aluminium spoon", "wrong-material", "Aluminium is a metal.")], ["Plastic is a poor conductor."], None)
q("cv-017", B, 2, CV, "Which of these materials can be used to carry electricity to a lamp?", "Aluminium", [W("Glass", "wrong-material", "Glass is an insulator."), W("Rubber", "wrong-material", "Rubber is an insulator."), W("Paper", "wrong-material", "Paper is an insulator.")], ["Aluminium is a metal conductor."], None)
q("cv-018", B, 2, CV, "Which one is the best material to cover an electric cable?", "Plastic", [W("Copper", "wrong-material", "Copper conducts electricity."), W("Iron", "wrong-material", "Iron conducts electricity."), W("Steel", "wrong-material", "Steel conducts electricity.")], ["Plastic is an insulator, so it is safe."], None)
q("cv-019", B, 1, CV, "Which circuit has the dimmest bulbs?", "Circuit C", [W("Circuit A", "wrong-circuit", "A has only one bulb."), W("Circuit B", "wrong-circuit", "B has fewer bulbs than C."), W("They are all equally dim", "wrong-idea", "The circuits have different numbers of bulbs.")], ["C has the most bulbs sharing one cell."], lambda: pair([circuit([[("L", "P")], [("S", "S", True), ("B", 1)]], caption="Circuit A", W=200), circuit([[("L", "P"), ("L", "Q")], [("S", "S", True), ("B", 1)]], caption="Circuit B", W=260), circuit([[("L", "P"), ("L", "Q"), ("L", "R")], [("S", "S", True), ("B", 1)]], caption="Circuit C", W=300)]))
q("cv-020", B, 1, CV, "What happens to the current when more bulbs are added in series?", "The current becomes smaller", [W("The current becomes larger", "reversed", "More bulbs make it harder for the current."), W("The current does not change", "wrong-idea", "The current changes."), W("The current stops", "wrong-idea", "The circuit is still complete.")], ["More bulbs in one loop make the current smaller."], None)
q("cv-021", B, 2, CV, "A student places a coin in the gap of a circuit and the bulb lights. Which statement about the coin is correct?", "The coin is a conductor", [W("The coin is an insulator", "reversed", "An insulator would stop the bulb lighting."), W("The coin is a battery", "wrong-idea", "The coin does not supply energy."), W("The coin is a bulb", "wrong-idea", "The coin only carries current.")], ["The bulb lit, so the coin conducts."], None)
q("cv-022", B, 2, CV, "A rubber band is placed in the gap of a circuit. The bulb does not light. What does this show?", "The rubber band is an insulator", [W("The rubber band is a conductor", "reversed", "A conductor would let the bulb light."), W("The battery is flat", "wrong-idea", "The test does not show this."), W("The bulb is fused", "wrong-idea", "The test does not show this.")], ["Rubber does not let electricity through."], None)
q("cv-023", B, 2, CV, "Metals are good conductors of electricity. Which of the following is a metal?", "A paper clip made of steel", [W("A glass marble", "wrong-material", "Glass is not a metal."), W("A rubber ball", "wrong-material", "Rubber is not a metal."), W("A wooden block", "wrong-material", "Wood is not a metal.")], ["Steel is a metal."], None)
q("cv-024", B, 1, CV, "Two cells are joined in series. How does this compare with using one cell?", "The bulb gets more energy and is brighter", [W("The bulb gets less energy and is dimmer", "reversed", "Two cells give more energy."), W("The bulb is the same brightness", "wrong-idea", "More cells make a difference."), W("The bulb will not light", "wrong-idea", "It will light.")], ["Two cells in series push a bigger current."], None)
q("cv-025", B, 1, CV, "Which change will make the bulb in a series circuit brighter?", "Adding another battery in series", [W("Adding another bulb in series", "reversed", "This makes the bulb dimmer."), W("Making the wire longer", "wrong-change", "Wire length is not the answer."), W("Opening the switch", "wrong-change", "An open switch turns the bulb off.")], ["More cells give a larger current."], None)

